}","customjavascript":"let selectedAttendees = [];
let registrationCounter = 0;

 

$(document).ready(function(){

    let courseId = "{{request.params['id'] | xml_escape}}";
    
    var attendeeid= "{{user.contactid}}";
    var selector='.contactimg';
    loadImage(attendeeid,selector);   

    //Get the image
    webapi.safeAjax({
        type: "GET",
        url: "/_api/msdynce_courses({{request.params['id']}})?$select=msdynce_entityimage",
        contentType: "application/json",
        success: function (res, status) {
            if (res && res.msdynce_entityimage){
                imgBaseString = res.msdynce_entityimage;
                $(".image-view").attr("src", "data:image/png;base64," + imgBaseString);
            }
        }
    });

    $(".card-body span.date").each(function(){
        var date = moment.utc(this.innerHTML);
        $(this).text(moment(date).local().format("MMMM DD"));
    });

    $(".card-body span.time").each(function(){
        var time = moment.utc(this.innerHTML);
        $(this).text(moment(time).local().format("hh:mm a"));
    });

      

    function loadImage(objectid, selector){
      var imgURL = "";
      var query="/_api/contacts(" + objectid + ")?$select=entityimage";
      webapi.safeAjax({
      type: "GET",
      url: query,
      contentType: "application/json",
      success: function (res, status) {
          if (res.entityimage){
            var imgBaseString = res.entityimage;
            var imgHTML = "";
            imgURL = "data:image/png;base64," + imgBaseString;
            $(selector).attr("src", imgURL);
          }   
        }
      });
    }

    
});","displayorder":12,"enablerating":false,"enabletracking":false,"excludefromsearch":false,"feedbackpolicy":756150000,"hiddenfromsitemap":false,"isroot":false,"pagetemplateid":"4cc21211-5fcf-f111-a05a-70a8a52c89ad","parentpageid":"58120917-5fcf-f111-a05a-70a8a52c89ad","partialurl":"registration-success","publishingstateid":"de110917-5fcf-f111-a05a-70a8a52c89ad","rootwebpageid":"27c21211-5fcf-f111-a05a-70a8a52c89ad","sharedpageconfiguration":true,"summary":"<p>This is sample landing page for you to start building your website</p>","title":"Registration Success"}
